use std::io::{Error, ErrorKind, Read, Result, Seek};

use super::TraceHeaderType;
use bitflags::bitflags;
use uuid::{uuid, Uuid};

use crate::helper::{u16_from_le_slice, u32_from_le_slice, u64_from_le_slice};

const MODERN_EVENT_HEADER_SIZE: usize = 80;

/// A modern event
///
/// Usually a event produced by a manifest based provider.
///
/// Since the API is backwards compatible, modern events can
/// also be generated by other providers (MOF based).
#[derive(Debug)]
pub struct ModernEvent {
    pub header: ModernEventHeader,
    pub extended_header: Option<Vec<u8>>,
    pub payload: Vec<u8>,
}

impl ModernEvent {
    /// Parse a ModernEvent from Windows native binary representation
    pub(crate) fn parse<R: Read + Seek>(buf: &mut R) -> Result<ModernEvent> {
        let header = ModernEventHeader::parse(buf)?;

        if header.event_flags.contains(Flags::ExtendedInfo) {
            log::warn!("Events containing extended header items not jet supported.");
            todo!();
        }

        let payload_size = header.size - header.length() as u16;

        let mut payload: Vec<u8> = vec![0u8; payload_size as usize];

        buf.read_exact(&mut payload)?;

        Ok(ModernEvent {
            header,
            extended_header: None,
            payload,
        })
    }
}

proc_etw_manifest::include_manifests!("./manifest");

